// System Health Status Checker for {{CLINIC_NAME}}
const now = new Date();
const timezone = '{{TIMEZONE}}';

console.log(`🏥 Running system health check for {{CLINIC_NAME}} - ${now.toLocaleString('en-US', { timeZone: timezone })}`);

// Collect all system responses
const bookingSystem = $items('📅 Ping Booking System')[0] || {};
const twilioApi = $items('📱 Ping Twilio API')[0] || {};
const googleSheetsApi = $items('📊 Ping Google Sheets API')[0] || {};

// System status tracking
const systemStatus = {
  timestamp: now.toISOString(),
  clinic_name: '{{CLINIC_NAME}}',
  check_type: 'Hourly Health Monitor',

  // Individual system status
  booking_system: {
    status: bookingSystem.statusCode === 200 ? 'HEALTHY' : 'DOWN',
    status_code: bookingSystem.statusCode || 'NO_RESPONSE',
    response_time: bookingSystem.responseTime || 'TIMEOUT',
    url: '{{BOOKING_SYSTEM_API_URL}}'
  },

  twilio_api: {
    status: twilioApi.statusCode === 200 ? 'HEALTHY' : 'DOWN',
    status_code: twilioApi.statusCode || 'NO_RESPONSE',
    response_time: twilioApi.responseTime || 'TIMEOUT',
    service: 'Twilio SMS API'
  },

  google_sheets_api: {
    status: googleSheetsApi.statusCode === 200 ? 'HEALTHY' : 'DOWN',
    status_code: googleSheetsApi.statusCode || 'NO_RESPONSE',
    response_time: googleSheetsApi.responseTime || 'TIMEOUT',
    service: 'Google Sheets API'
  }
};

// Calculate overall system health
const healthySystems = Object.values(systemStatus)
  .filter(system => typeof system === 'object' && system.status === 'HEALTHY')
  .length;

const totalSystems = 3; // booking, twilio, google sheets
const healthPercentage = (healthySystems / totalSystems) * 100;

// Determine overall status
let overallStatus = 'HEALTHY';
let alertLevel = 'INFO';

if (healthPercentage < 100) {
  overallStatus = 'DEGRADED';
  alertLevel = 'WARNING';
}

if (healthPercentage < 67) {
  overallStatus = 'CRITICAL';
  alertLevel = 'CRITICAL';
}

// System summary
systemStatus.overall = {
  status: overallStatus,
  health_percentage: healthPercentage,
  healthy_systems: healthySystems,
  total_systems: totalSystems,
  alert_level: alertLevel
};

// Generate alert message if needed
const failedSystems = [];
if (systemStatus.booking_system.status !== 'HEALTHY') {
  failedSystems.push('Booking System API');
}
if (systemStatus.twilio_api.status !== 'HEALTHY') {
  failedSystems.push('Twilio SMS Service');
}
if (systemStatus.google_sheets_api.status !== 'HEALTHY') {
  failedSystems.push('Google Sheets Integration');
}

if (failedSystems.length > 0) {
  systemStatus.alert_message = `🚨 SYSTEM ALERT: ${failedSystems.join(', ')} ${failedSystems.length === 1 ? 'is' : 'are'} currently experiencing issues. Immediate attention required.`;
  systemStatus.impact_assessment = `This may affect: ${failedSystems.includes('Booking System API') ? 'Online appointments, ' : ''}${failedSystems.includes('Twilio SMS Service') ? 'SMS notifications, ' : ''}${failedSystems.includes('Google Sheets Integration') ? 'Data logging and reporting' : ''}`.replace(/, $/, '');
} else {
  systemStatus.alert_message = '✅ All systems operational - no action required';
  systemStatus.impact_assessment = 'All clinic automation systems are functioning normally';
}

// Check if this is a critical failure requiring immediate notification
systemStatus.requires_immediate_alert = alertLevel === 'CRITICAL' || alertLevel === 'WARNING';

console.log(`📊 Health check complete: ${overallStatus} (${healthPercentage}% healthy) - ${systemStatus.alert_message}`);

return [{ json: systemStatus }];

